    pub wrap_chars: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            check: false,
            print: false,
            fail_on_change: false,
            wrap: true,
            wraplen: 80,
            wrapmin: 70,
            tabsize: 2,
            usetabs: false,
