#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub check: bool,
    pub print: bool,
    pub fail_on_change: bool,
    pub wrap: bool,
    pub wraplen: usize,
    pub wrapmin: usize,
    pub tabsize: usize,
    pub usetabs: bool,
    pub stdin: bool,
    pub config: Option<PathBuf>,
    pub verbosity: String,
    pub lists: Vec<String>,
    pub verbatims: Vec<String>,
    pub no_indent_envs: Vec<String>,
    pub wrap_chars: Vec<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            check: false,
            print: false,
            fail_on_change: false,
            wrap: true,
            wraplen: 80,
            wrapmin: 70,
            tabsize: 2,
            usetabs: false,
            stdin: false,
            config: None,
            verbosity: "warn".to_string(),
            lists: vec![
                "itemize".to_string(),
                "enumerate".to_string(),
                "description".to_string(),
                "inlineroman".to_string(),
                "inventory".to_string(),
            ],
            verbatims: vec![
                "verbatim".to_string(),
                "Verbatim".to_string(),
                "lstlisting".to_string(),
                "minted".to_string(),
                "comment".to_string(),
            ],
            no_indent_envs: vec![
                "document".to_string(),
            ],
            wrap_chars: vec![],
        }
    }
}

#[derive(Debug, Serialize, Deserialize)]
struct ConfigFile {
    #[serde(default)]
    check: Option<bool>,
    #[serde(default)]
    print: Option<bool>,
    #[serde(default)]
    fail_on_change: Option<bool>,
    #[serde(default)]
    wrap: Option<bool>,
    #[serde(default)]
    wraplen: Option<usize>,
    #[serde(default)]
    wrapmin: Option<usize>,
    #[serde(default)]
    tabsize: Option<usize>,
    #[serde(default)]
    tabchar: Option<String>,
    #[serde(default)]
    stdin: Option<bool>,
    #[serde(default)]
    verbosity: Option<String>,
    #[serde(default)]
    lists: Option<Vec<String>>,
    #[serde(default)]
    verbatims: Option<Vec<String>>,
    #[serde(default)]
    no_indent_envs: Option<Vec<String>>,
    #[serde(default)]
    wrap_chars: Option<Vec<String>>,
}

impl Config {
    pub fn from_args(args: &Args) -> Self {
        let mut config = Config::default();

        // Load config file if not disabled
        if !args.noconfig {
            if let Some(config_path) = &args.config {
                if let Ok(cfg) = Self::load_config_file(config_path) {
                    config = cfg;
                }
            } else {
                // Try to find config file in standard locations
                if let Ok(cfg) = Self::find_and_load_config() {
                    config = cfg;
                }
            }
        }

        // Command line arguments override config file
        config.check = args.check;
        config.print = args.print;
        config.fail_on_change = args.fail_on_change;
        config.stdin = args.stdin;
        config.usetabs = args.usetabs;
        config.tabsize = args.tabsize;

        if args.nowrap {
            config.wrap = false;
        }

        if args.wraplen != 80 {
            config.wraplen = args.wraplen;
            // Adjust wrapmin based on wraplen
            config.wrapmin = (args.wraplen as f64 * 0.875) as usize;
        }

        config.config = args.config.clone();
        config.verbosity = args.verbosity();

        config
    }

    fn load_config_file(path: &PathBuf) -> Result<Config, Box<dyn std::error::Error>> {
        let content = fs::read_to_string(path)?;
        let cfg_file: ConfigFile = toml::from_str(&content)?;

        let mut config = Config::default();

        if let Some(v) = cfg_file.check {
            config.check = v;
        }
        if let Some(v) = cfg_file.print {
            config.print = v;
        }
        if let Some(v) = cfg_file.fail_on_change {
            config.fail_on_change = v;
        }
        if let Some(v) = cfg_file.wrap {
            config.wrap = v;
        }
        if let Some(v) = cfg_file.wraplen {
            config.wraplen = v;
        }
        if let Some(v) = cfg_file.wrapmin {
            config.wrapmin = v;
        }
        if let Some(v) = cfg_file.tabsize {
            config.tabsize = v;
        }
        if let Some(v) = cfg_file.tabchar {
            config.usetabs = v == "tab";
        }
        if let Some(v) = cfg_file.stdin {
            config.stdin = v;
        }
        if let Some(v) = cfg_file.verbosity {
            config.verbosity = v;
        }
        if let Some(v) = cfg_file.lists {
            config.lists = v;
        }
        if let Some(v) = cfg_file.verbatims {
            config.verbatims = v;
        }
        if let Some(v) = cfg_file.no_indent_envs {
            config.no_indent_envs = v;
        }
        if let Some(v) = cfg_file.wrap_chars {
            config.wrap_chars = v;
        }

        Ok(config)
    }

    fn find_and_load_config() -> Result<Config, Box<dyn std::error::Error>> {
        // Try current working directory
        if let Ok(cfg) = Self::load_config_file(&PathBuf::from("tex-fmt.toml")) {
            return Ok(cfg);
        }

        // Try user config directory
        if let Some(home) = dirs::home_dir() {
            let config_path = home.join(".config/tex-fmt/tex-fmt.toml");
            if let Ok(cfg) = Self::load_config_file(&config_path) {
                return Ok(cfg);
            }
        }

        Err("No config file found".into())
    }
}
