use crate::config::Config;
use log::{warn, trace, info};
use std::collections::HashSet;

pub struct Formatter {
    config: Config,
}

#[derive(Debug, Clone)]
struct Line {
    content: String,
    indent_level: usize,
    is_empty: bool,
}

impl Formatter {
    pub fn new(config: Config) -> Self {
        Formatter { config }
    }

    pub fn format(&self, content: &str, filename: &str) -> String {
        info!("tex-fmt {}: Formatting started. ", filename);

        let lines: Vec<&str> = content.lines().collect();
        let formatted_lines = self.format_lines(&lines, filename);

        info!("tex-fmt {}: Formatting complete. ", filename);

        formatted_lines.join("\n") + if content.ends_with('\n') { "\n" } else { "" }
    }

    fn format_lines(&self, lines: &[&str], filename: &str) -> Vec<String> {
        let mut result = Vec::new();
        let mut indent_stack = vec![0];
        let mut in_verbatim = false;
        let mut verbatim_env = String::new();
        let mut line_idx = 1;

        for line in lines {
            let visual_indent = self.get_visual_indent(line);

            // Check for verbatim environment start
            if !in_verbatim {
                if let Some(env) = self.detect_begin(line) {
                    if self.config.verbatims.contains(&env) {
                        in_verbatim = true;
                        verbatim_env = env;
                    }
                }
            }

            // If in verbatim, don't reformat
            if in_verbatim {
                result.push(line.to_string());

                if self.detect_end(line) == Some(verbatim_env.clone()) {
                    in_verbatim = false;
                    verbatim_env.clear();
                }

                line_idx += 1;
                continue;
            }

            // Process line
            let processed = self.process_line(line, &mut indent_stack, filename, line_idx);
            result.push(processed);
            line_idx += 1;
        }

        // Report indent issues
        if let Some(&last_indent) = indent_stack.last() {
            if last_indent != 0 {
                warn!("tex-fmt {}: Indent does not return to zero. Last non-indented line is line {} ", filename, line_idx - 1);
            }
        }

        result
    }

    fn process_line(&self, line: &str, indent_stack: &mut Vec<usize>, filename: &str, line_idx: usize) -> String {
        let trimmed = line.trim();

        // Empty lines
        if trimmed.is_empty() {
            return String::new();
        }

        // Update indent stack based on begin/end commands
        self.update_indent_stack(trimmed, indent_stack);

        // Get the target indent level
        let target_indent = *indent_stack.last().unwrap_or(&0);

        // Create the indented line
        let indent_str = if self.config.usetabs {
            "\t".repeat(target_indent)
        } else {
            " ".repeat(target_indent * self.config.tabsize)
        };

        let indented = format!("{}{}", indent_str, trimmed);

        // Apply line wrapping if enabled
        let wrapped = if self.config.wrap {
            self.wrap_line(&indented, target_indent, line_idx, filename)
        } else {
            indented
        };

        trace!("tex-fmt {}: Line {} ({}). Indent: actual = {}, visual = {}: {}", 
               filename, line_idx, line_idx, 
               target_indent * self.config.tabsize,
               self.get_visual_indent(&wrapped),
               trimmed);

        wrapped
    }

    fn update_indent_stack(&self, line: &str, stack: &mut Vec<usize>) {
        let current_indent = stack.last().copied().unwrap_or(0);

        // Check for \end commands at the start
        if let Some(env) = self.detect_end(line) {
            if !self.config.no_indent_envs.contains(&env) {
                if stack.len() > 1 {
                    stack.pop();
                }
            }
        }

        // Check for \begin commands
        if let Some(env) = self.detect_begin(line) {
            if !self.config.no_indent_envs.contains(&env) {
                if self.config.lists.contains(&env) {
                    stack.push(current_indent + 1);
                } else if !self.config.verbatims.contains(&env) {
                    stack.push(current_indent + 1);
                }
            }
        }
    }

    fn detect_begin(&self, line: &str) -> Option<String> {
        if let Some(caps) = regex::Regex::new(r"\\begin\{([^}]+)\}")
            .ok()
            .and_then(|re| re.captures(line))
        {
            return caps.get(1).map(|m| m.as_str().to_string());
        }
        None
    }

    fn detect_end(&self, line: &str) -> Option<String> {
        if let Some(caps) = regex::Regex::new(r"\\end\{([^}]+)\}")
            .ok()
            .and_then(|re| re.captures(line))
        {
            return caps.get(1).map(|m| m.as_str().to_string());
        }
        None
    }

    fn get_visual_indent(&self, line: &str) -> usize {
        let mut count = 0;
        for ch in line.chars() {
            if ch == ' ' {
                count += 1;
            } else if ch == '\t' {
                count += self.config.tabsize;
            } else {
                break;
            }
        }
        count
    }

    fn wrap_line(&self, line: &str, indent_level: usize, line_idx: usize, filename: &str) -> String {
        let indent_size = if self.config.usetabs {
            indent_level * self.config.tabsize
        } else {
            indent_level * self.config.tabsize
        };

        let max_len = self.config.wraplen;

        if line.len() <= max_len {
            return line.to_string();
        }

        let trimmed = line.trim_start();
        let indent_str = if self.config.usetabs {
            "\t".repeat(indent_level)
        } else {
            " ".repeat(indent_size)
        };

        let continuation_indent = indent_str.clone() + "  ";
        let continuation_size = indent_size + 2;

        let mut result = String::new();
        let mut current_line = indent_str.clone();
        let mut words = trimmed.split_whitespace().peekable();

        while let Some(word) = words.next() {
            let test_line = if current_line.trim().is_empty() {
                format!("{}{}", indent_str, word)
            } else {
                format!("{} {}", current_line, word)
            };

            if test_line.len() <= max_len {
                current_line = test_line;
            } else {
                // Line too long, need to wrap
                if !current_line.trim().is_empty() {
                    result.push_str(&current_line);
                    result.push('\n');
                }
                current_line = format!("{}{}", continuation_indent, word);
            }
        }

        if !current_line.trim().is_empty() {
            result.push_str(&current_line);
        }

        result
    }
}
