    }
}

fn log_warn(filename: &str, message: &str) {
    if !should_hide_warnings() {
        eprintln!("WARN: tex-fmt {}: {}", filename, message);
    }
}

fn log_info(filename: &str, message: &str) {
    if should_show_info() {
        eprintln!("INFO: tex-fmt {}: {}", filename, message);
    }
}

fn log_trace(filename: &str, message: &str) {
    if should_show_trace() {
        eprintln!("TRACE: tex-fmt {}: {}", filename, message);
    }
}

fn should_hide_warnings() -> bool {
    env::var("QUIET").is_ok()
}

fn should_show_info() -> bool {
    env::var("VERBOSE").is_ok()
}

fn should_show_trace() -> bool {
    env::var("TRACE").is_ok()
}

fn process_stdin(config: &Config) {
    let mut buffer = String::new();
    io::stdin().read_to_string(&mut buffer).expect("Failed to read stdin");

    let formatter = Formatter::new(config.clone());
    let formatted = formatter.format(&buffer, "<stdin>");
    print!("{}", formatted);
}

fn process_files(files: &[String], config: &Config, args: &Args) {
    let mut has_changes = false;

    for file_path in files {
        let path = Path::new(file_path);
        if !should_process_file(path) {
            continue;
        }

        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                log_warn(file_path, &format!("Failed to read: {}", e));
                continue;
            }
        };

        let formatter = Formatter::new(config.clone());
        let formatted = formatter.format(&content, file_path);

