                    args.fail_on_change = true;
                }
                "-n" | "--nowrap" => {
                    args.nowrap = true;
                }
                "-l" | "--wraplen" => {
                    i += 1;
                    if i < argv.len() {
                        args.wraplen = argv[i].parse().unwrap_or(80);
                    }
                }
                "-t" | "--tabsize" => {
                    i += 1;
                    if i < argv.len() {
                        args.tabsize = argv[i].parse().unwrap_or(2);
                    }
                }
                "--usetabs" => {
                    args.usetabs = true;
                }
                "-s" | "--stdin" => {
                    args.stdin = true;
                }
                "--config" => {
                    i += 1;
                    if i < argv.len() {
                        args.config = Some(PathBuf::from(&argv[i]));
                    }
                }
                "--noconfig" => {
                    args.noconfig = true;
                }
                "-v" | "--verbose" => {
                    args.verbose = true;
                }
                "-q" | "--quiet" => {
                    args.quiet = true;
                }
                "--trace" => {
                    args.trace = true;
                }
                "--completion" => {
                    i += 1;
                    if i < argv.len() {
                        args.completion = Some(argv[i].clone());
                    }
                }
                "--man" => {
                    args.man = true;
                }
                "--args" => {
                    args.args = true;
                }
                "-r" | "--recursive" => {
                    args.recursive = true;
                }
                s if s.starts_with('-') => {
                    eprintln!("Unknown option: {}", s);
                    std::process::exit(1);
                }
                _ => {
                    args.files.push(argv[i].clone());
                }
            }
            i += 1;
        }

        // Determine verbosity
        if args.trace {
            args.verbosity = "trace".to_string();
        } else if args.verbose {
            args.verbosity = "verbose".to_string();
        } else if args.quiet {
            args.verbosity = "quiet".to_string();
        } else {
            args.verbosity = "warn".to_string();
        }

        args
    }
}

