use crate::config::Config;

pub struct Formatter {
    config: Config,
}

impl Formatter {
    pub fn new(config: Config) -> Self {
        Formatter { config }
    }

    pub fn format(&self, content: &str, filename: &str) -> String {
        let lines: Vec<&str> = content.lines().collect();
        let formatted_lines = self.format_lines(&lines, filename);

        formatted_lines.join("\n") + if content.ends_with('\n') { "\n" } else { "" }
    }

    fn format_lines(&self, lines: &[&str], filename: &str) -> Vec<String> {
        let mut result = Vec::new();
        let mut indent_stack = vec![0];
        let mut in_verbatim = false;
        let mut verbatim_env = String::new();
        let mut line_idx = 1;
        let mut warns_printed = std::collections::HashSet::new();

        for line in lines {
            // Check for verbatim environment start
            if !in_verbatim {
                if let Some(env) = self.detect_begin(line) {
                    if self.config.verbatims.contains(&env) {
                        in_verbatim = true;
                        verbatim_env = env;
                    }
                }
            }

            // If in verbatim, don't reformat
            if in_verbatim {
                result.push(line.to_string());

                if self.detect_end(line) == Some(verbatim_env.clone()) {
                    in_verbatim = false;
                    verbatim_env.clear();
                }

                line_idx += 1;
                continue;
            }

            // Process line
            let (processed, warn) = self.process_line(line, &mut indent_stack, filename, line_idx);
            if let Some(w) = warn {
                if !warns_printed.contains(&w) {
                    eprintln!("WARN: tex-fmt {}: {}", filename, w);
                    warns_printed.insert(w);
                }
            }
            result.push(processed);
            line_idx += 1;
        }

        // Report indent issues
        if let Some(&last_indent) = indent_stack.last() {
            if last_indent != 0 && !warns_printed.contains("Indent does not return") {
                eprintln!("WARN: tex-fmt {}: Indent does not return to zero. Last non-indented line is line {} ", filename, line_idx - 1);
            }
        }

        result
    }

    fn process_line(&self, line: &str, indent_stack: &mut Vec<usize>, filename: &str, line_idx: usize) -> (String, Option<String>) {
        let trimmed = line.trim();

        // Empty lines
        if trimmed.is_empty() {
            return (String::new(), None);
        }

        // Check for end before updating indent
        let mut warn = None;

        // Update indent stack based on begin/end commands
        self.update_indent_stack(trimmed, indent_stack, &mut warn);

        // Get the target indent level
        let target_indent = *indent_stack.last().unwrap_or(&0);

        // Check if indent is negative
        if target_indent as i32 > line_idx as i32 {
            warn = Some(format!("Line {} ({}). Indent is negative. {}", line_idx, line_idx, trimmed));
        }

        // Create the indented line
        let indent_str = if self.config.usetabs {
            "\t".repeat(target_indent)
        } else {
            " ".repeat(target_indent * self.config.tabsize)
        };

        let indented = format!("{}{}", indent_str, trimmed);

        // Apply line wrapping if enabled
        let wrapped = if self.config.wrap {
            self.wrap_line(&indented, target_indent)
        } else {
            indented
        };

        (wrapped, warn)
    }

    fn update_indent_stack(&self, line: &str, stack: &mut Vec<usize>, warn: &mut Option<String>) {
        let current_indent = stack.last().copied().unwrap_or(0);

        // Check for \end commands at the start
        if let Some(env) = self.detect_end(line) {
            if !self.config.no_indent_envs.contains(&env) {
                if stack.len() > 1 {
                    stack.pop();
                }
            }
        }

        // Check for \begin commands
        if let Some(env) = self.detect_begin(line) {
            if !self.config.no_indent_envs.contains(&env) {
                if self.config.lists.contains(&env) {
                    stack.push(current_indent + 1);
                } else if !self.config.verbatims.contains(&env) {
                    stack.push(current_indent + 1);
                }
            }
        }
    }

    fn detect_begin(&self, line: &str) -> Option<String> {
        if let Some(start) = line.find("\\begin{") {
            if let Some(end) = line[start..].find('}') {
                let env = line[start + 7..start + end].to_string();
                return Some(env);
            }
        }
        None
    }

    fn detect_end(&self, line: &str) -> Option<String> {
        if let Some(start) = line.find("\\end{") {
            if let Some(end) = line[start..].find('}') {
                let env = line[start + 5..start + end].to_string();
                return Some(env);
            }
        }
        None
    }

    fn wrap_line(&self, line: &str, indent_level: usize) -> String {
        let max_len = self.config.wraplen;

        if line.len() <= max_len {
            return line.to_string();
        }

        let trimmed = line.trim_start();
        let indent_size = if self.config.usetabs {
            indent_level * self.config.tabsize
        } else {
            indent_level * self.config.tabsize
        };
