use std::fs;
use std::path::Path;
use std::io::{self, Read};
use std::process;
use std::env;

mod cli;
mod config;
mod formatter;

use cli::Args;
use config::Config;
use formatter::Formatter;

fn main() {
    let args = Args::parse(&env::args().collect::<Vec<_>>());

    // Handle special output modes that exit immediately
    if let Some(shell) = &args.completion {
        generate_completion(shell);
        return;
    }

    if args.man {
        generate_man();
        return;
    }

    if args.args {
        print_args(&args);
        return;
    }

    // Load configuration
    let config = Config::from_args(&args);

    // Process files or stdin
    if args.stdin {
        process_stdin(&config);
    } else if args.files.is_empty() && !args.recursive {
        eprintln!("Error: No files specified");
        process::exit(1);
    } else if args.recursive {
        process_recursive(&args.files, &config, &args);
    } else {
        process_files(&args.files, &config, &args);
    }
}

fn process_stdin(config: &Config) {
    let mut buffer = String::new();
    io::stdin().read_to_string(&mut buffer).expect("Failed to read stdin");

    let formatter = Formatter::new(config.clone());
    let formatted = formatter.format(&buffer, "<stdin>");
    print!("{}", formatted);
}

fn process_files(files: &[String], config: &Config, args: &Args) {
    let mut has_changes = false;

    for file_path in files {
        let path = Path::new(file_path);
        if !should_process_file(path) {
            continue;
        }

        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("WARN: tex-fmt {}: Failed to read: {}", file_path, e);
                continue;
            }
        };

        let formatter = Formatter::new(config.clone());
        let formatted = formatter.format(&content, file_path);

        let content_changed = formatted != content;

        if args.print {
            // Always print formatted output when --print is used
            print!("{}", formatted);
        } else if content_changed {
            has_changes = true;

            if args.check {
                eprintln!("ERROR: tex-fmt {}: Incorrect formatting. ", file_path);
                process::exit(1);
            }

            // Write to file
            if let Err(e) = fs::write(path, &formatted) {
                eprintln!("WARN: tex-fmt {}: Failed to write: {}", file_path, e);
            }
        }
    }

    if args.fail_on_change && has_changes {
        process::exit(1);
    }
}

fn process_recursive(dirs: &[String], config: &Config, args: &Args) {
    let search_dir = if dirs.is_empty() { "." } else { &dirs[0] };

    if let Ok(entries) = fs::read_dir(search_dir) {
        for entry in entries.filter_map(|e| e.ok()) {
            let path = entry.path();
            if path.is_file() && should_process_file(&path) {
                let file_path = path.to_string_lossy().to_string();
                process_files(&[file_path], config, args);
            } else if path.is_dir() {
                // Recursively process subdirectories
                let subdir = vec![path.to_string_lossy().to_string()];
                process_recursive(&subdir, config, args);
            }
        }
    }
}

fn should_process_file(path: &Path) -> bool {
    match path.extension().and_then(|s| s.to_str()) {
        Some("tex") | Some("bib") | Some("cls") | Some("sty") => true,
        _ => false,
    }
}

fn generate_completion(shell: &str) {
    eprintln!("Completion generation for {} not yet implemented", shell);
}

fn generate_man() {
    eprintln!("Man page generation not yet implemented");
}

fn print_args(args: &Args) {
    let config = Config::from_args(args);
    println!("tex-fmt");
    println!("  check:                   {}", args.check);
    println!("  print:                   {}", args.print);
    println!("  fail-on-change:          {}", args.fail_on_change);
    println!("  wrap:                    {}", config.wrap);
    println!("  wraplen:                 {}", config.wraplen);
    println!("  wrapmin:                 {}", config.wrapmin);
    println!("  tabsize:                 {}", config.tabsize);
    println!("  tabchar:                 {}", if config.usetabs { "tab" } else { "space" });
    println!("  stdin:                   {}", args.stdin);
    println!("  config:                  {:?}", args.config);
    println!("  verbosity:               {}", args.verbosity);
    println!("  lists:                   ");
    for list in &config.lists {
        println!("                           {}", list);
    }
    println!("  verbatims:               ");
    for verb in &config.verbatims {
        println!("                           {}", verb);
    }
    println!("  no-indent-envs:          ");
    for env in &config.no_indent_envs {
        println!("                           {}", env);
    }
    println!("  wrap-chars:              ");
    for _ch in &config.wrap_chars {
        println!("                           ");
    }
}
