use crate::config::Config;

pub struct Formatter {
    config: Config,
}

impl Formatter {
    pub fn new(config: Config) -> Self {
        Formatter { config }
    }

    pub fn format(&self, content: &str, _filename: &str) -> String {
        let lines: Vec<&str> = content.lines().collect();
        let formatted_lines = self.format_lines(&lines, _filename);

        formatted_lines.join("\n") + if content.ends_with('\n') { "\n" } else { "" }
    }

    fn format_lines(&self, lines: &[&str], filename: &str) -> Vec<String> {
        let mut result = Vec::new();
        let mut indent_stack = vec![0];
        let mut in_verbatim = false;
        let mut verbatim_env = String::new();
        let mut line_idx = 1;
        let mut prev_allows_continuation = false;

        let mut i = 0;
        while i < lines.len() {
            let line = lines[i];

            // Check for verbatim environment start
            if !in_verbatim {
                if let Some(env) = self.detect_begin(line) {
                    if self.config.verbatims.contains(&env) {
                        in_verbatim = true;
                        verbatim_env = env;
                    }
                }
            }

            // If in verbatim, don't reformat
            if in_verbatim {
                result.push(line.to_string());
                prev_allows_continuation = false;

                if self.detect_end(line) == Some(verbatim_env.clone()) {
                    in_verbatim = false;
                    verbatim_env.clear();
                }

                i += 1;
                line_idx += 1;
                continue;
            }

            // Process non-empty lines
            let trimmed = line.trim();

            if trimmed.is_empty() {
                result.push(String::new());
                prev_allows_continuation = false;
                i += 1;
                line_idx += 1;
                continue;
            }

            // Check if this line is a continuation
            let is_continuation = !trimmed.starts_with('\\') && prev_allows_continuation;

            // Handle \end before changing indent
            if !is_continuation {
                if let Some(_env) = self.detect_end(trimmed) {
                    if indent_stack.len() > 1 {
                        indent_stack.pop();
                    }
                }
            }

            let current_indent = *indent_stack.last().unwrap_or(&0);

            // For continuation lines, add extra indentation
            let target_indent = if is_continuation {
                current_indent + 1
            } else {
                current_indent
            };

            // Create indented line
            let indent_str = self.make_indent(target_indent);
            let indented = format!("{}{}", indent_str, trimmed);

            // Apply wrapping
            let wrapped = if self.config.wrap {
                self.wrap_line(&indented, target_indent)
            } else {
                indented
            };

            result.push(wrapped);

            // Handle \begin after processing the line
            if !is_continuation {
                if let Some(env) = self.detect_begin(trimmed) {
                    if !self.config.no_indent_envs.contains(&env) {
                        indent_stack.push(current_indent + 1);
                    }
                }
            }

            // Determine if the next line can be a continuation
            prev_allows_continuation = trimmed.starts_with('\\') && 
                                      !self.is_structural_command(trimmed);

            i += 1;
            line_idx += 1;
        }

