            if final_indent != 0 {
                eprintln!("WARN: tex-fmt {}: Indent does not return to zero. Last non-indented line is line {} ", filename, line_idx - 1);
            }
        }

        result
    }

    fn is_structural_command(&self, line: &str) -> bool {
        // Commands that should not have continuation lines following them
        line.contains("\\begin{") || 
        line.contains("\\end{") ||
        line.starts_with("\\documentclass") ||
        line.starts_with("\\usepackage") ||
        line.starts_with("\\author") ||
        line.starts_with("\\title") ||
        line.starts_with("\\date")
    }

    fn make_indent(&self, level: usize) -> String {
        if self.config.usetabs {
            // When using tabs, multiply tabsize by level
            "\t".repeat(level * self.config.tabsize)
        } else {
            " ".repeat(level * self.config.tabsize)
        }
    }

    fn detect_begin(&self, line: &str) -> Option<String> {
        if let Some(start) = line.find("\\begin{") {
            if let Some(end) = line[start..].find('}') {
                let env = line[start + 7..start + end].to_string();
                return Some(env);
            }
        }
        None
    }

    fn detect_end(&self, line: &str) -> Option<String> {
        if let Some(start) = line.find("\\end{") {
            if let Some(end) = line[start..].find('}') {
                let env = line[start + 5..start + end].to_string();
                return Some(env);
            }
        }
        None
    }

    fn wrap_line(&self, line: &str, indent_level: usize) -> String {
        let max_len = self.config.wraplen;

        if line.len() <= max_len {
            return line.to_string();
        }

        let trimmed = line.trim_start();
        let indent_size = if self.config.usetabs {
            indent_level * self.config.tabsize
        } else {
            indent_level * self.config.tabsize
        };
        let indent_str = if self.config.usetabs {
            "\t".repeat(indent_level * self.config.tabsize)
        } else {
            " ".repeat(indent_size)
        };

        let continuation_indent = indent_str.clone() + "  ";

        let mut result = String::new();
        let mut current_line = String::new();
        let words: Vec<&str> = trimmed.split_whitespace().collect();

        for word in words.iter() {
            let test_line = if current_line.is_empty() {
                format!("{}{}", indent_str, word)
            } else {
                format!("{} {}", current_line, word)
            };

            if test_line.len() <= max_len {
                current_line = test_line;
            } else {
                // Line too long, need to wrap
                if !current_line.is_empty() {
                    result.push_str(&current_line);
                    result.push('\n');
                }
                current_line = format!("{}{}", continuation_indent, word);
            }
        }

        if !current_line.is_empty() {
            result.push_str(&current_line);
        }

        result
    }
}
